extends Node3D
class_name TunisUrbanUtilitiesPass

var generated_count := 0
var medium_detail_nodes: Array[Node3D] = []
var high_detail_nodes: Array[Node3D] = []
var current_detail_level := 2

func build() -> void:
    add_to_group("quality_visual_detail")
    _build_power_poles()
    _build_meter_boxes()
    _build_street_cabinets()
    _build_service_cables()
    apply_visual_budget(current_detail_level)

func apply_visual_budget(detail_level: int) -> void:
    current_detail_level = clampi(detail_level, 0, 2)
    var show_medium := current_detail_level >= 1
    var show_high := current_detail_level >= 2
    for node in medium_detail_nodes:
        if is_instance_valid(node):
            node.visible = show_medium
    for node in high_detail_nodes:
        if is_instance_valid(node):
            node.visible = show_high

func _register_detail(node: Node3D, minimum_level: int) -> Node3D:
    if minimum_level >= 2:
        high_detail_nodes.append(node)
    elif minimum_level == 1:
        medium_detail_nodes.append(node)
    return node

func _material(color: Color, roughness := 0.86, metallic := 0.0) -> StandardMaterial3D:
    var material := StandardMaterial3D.new()
    material.albedo_color = color
    material.roughness = roughness
    material.metallic = metallic
    return material

func _box(parent: Node3D, pos: Vector3, size: Vector3, color: Color) -> MeshInstance3D:
    var instance := MeshInstance3D.new()
    var mesh := BoxMesh.new()
    mesh.size = size
    instance.mesh = mesh
    instance.position = pos
    instance.material_override = _material(color)
    parent.add_child(instance)
    generated_count += 1
    return instance

func _cylinder(parent: Node3D, pos: Vector3, radius: float, height: float, color: Color) -> MeshInstance3D:
    var instance := MeshInstance3D.new()
    var mesh := CylinderMesh.new()
    mesh.top_radius = radius
    mesh.bottom_radius = radius
    mesh.height = height
    instance.mesh = mesh
    instance.position = pos
    instance.material_override = _material(color)
    parent.add_child(instance)
    generated_count += 1
    return instance

func _build_power_poles() -> void:
    var root := Node3D.new()
    root.name = "UrbanPowerPoles"
    add_child(root)
    var positions := [Vector3(-72, 0, -54), Vector3(-20, 0, -54), Vector3(34, 0, -54), Vector3(84, 0, -54)]
    for pos in positions:
        var pole := Node3D.new()
        pole.position = pos
        root.add_child(pole)
        _cylinder(pole, Vector3(0, 4.1, 0), 0.13, 8.2, Color("#55524c"))
        var arm := _box(pole, Vector3(0, 7.5, 0), Vector3(2.3, 0.14, 0.14), Color("#343638"))
        _register_detail(arm, 1)
        for x in [-0.82, 0.0, 0.82]:
            var insulator := _cylinder(pole, Vector3(x, 7.7, 0), 0.07, 0.34, Color("#d3c8ad"))
            _register_detail(insulator, 2)

func _build_meter_boxes() -> void:
    var root := Node3D.new()
    root.name = "FacadeMeterBoxes"
    add_child(root)
    for pos in [Vector3(-45.2, 1.25, -64.6), Vector3(26.4, 1.25, -64.6), Vector3(77.0, 1.25, -8.0)]:
        var box := _box(root, pos, Vector3(0.72, 0.92, 0.22), Color("#b8b5aa"))
        _register_detail(box, 1)
        var slot := _box(root, pos + Vector3(0, 0.12, -0.13), Vector3(0.38, 0.22, 0.03), Color("#41484b"))
        _register_detail(slot, 2)

func _build_street_cabinets() -> void:
    var root := Node3D.new()
    root.name = "StreetUtilityCabinets"
    add_child(root)
    for pos in [Vector3(-8.2, 0.72, 42.0), Vector3(54.0, 0.72, 43.5)]:
        var cabinet := _box(root, pos, Vector3(1.15, 1.42, 0.62), Color("#68746b"))
        _register_detail(cabinet, 1)
        var handle := _box(root, pos + Vector3(0.39, 0.02, -0.33), Vector3(0.08, 0.25, 0.04), Color("#292d2c"))
        _register_detail(handle, 2)

func _build_service_cables() -> void:
    var root := Node3D.new()
    root.name = "UtilityServiceCables"
    add_child(root)
    _register_detail(root, 2)
    var segments := [
        [Vector3(-72, 7.55, -54), Vector3(-20, 7.55, -54)],
        [Vector3(-20, 7.55, -54), Vector3(34, 7.55, -54)],
        [Vector3(34, 7.55, -54), Vector3(84, 7.55, -54)]
    ]
    for pair in segments:
        _cable(root, pair[0], pair[1])

func _cable(parent: Node3D, start: Vector3, finish: Vector3) -> void:
    var points := 8
    for i in range(points):
        var t0 := float(i) / float(points)
        var t1 := float(i + 1) / float(points)
        var p0 := start.lerp(finish, t0)
        var p1 := start.lerp(finish, t1)
        p0.y -= sin(t0 * PI) * 0.75
        p1.y -= sin(t1 * PI) * 0.75
        var mid := (p0 + p1) * 0.5
        var length := p0.distance_to(p1)
        var segment := _cylinder(parent, mid, 0.025, length, Color("#202224"))
        segment.look_at(p1, Vector3.UP)
        segment.rotate_object_local(Vector3.RIGHT, PI * 0.5)

shader_type spatial;
render_mode diffuse_burley, specular_schlick_ggx;

uniform vec4 asphalt_color : source_color = vec4(0.12,0.13,0.14,1.0);
uniform vec4 patch_color : source_color = vec4(0.07,0.075,0.08,1.0);
uniform float scale_a = 0.17;
uniform float scale_b = 0.045;

float hash21(vec2 p) {
    p = fract(p * vec2(443.897, 441.423));
    p += dot(p, p + 19.19);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i=floor(p), f=fract(p);
    f=f*f*(3.0-2.0*f);
    return mix(
        mix(hash21(i), hash21(i+vec2(1,0)), f.x),
        mix(hash21(i+vec2(0,1)), hash21(i+vec2(1,1)), f.x),
        f.y
    );
}

void fragment() {
    vec3 wp = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
    float fine = noise(wp.xz * scale_a);
    float broad = noise(wp.xz * scale_b);
    float patch = smoothstep(0.67, 0.84, broad);
    vec3 col = asphalt_color.rgb * (0.88 + fine * 0.18);
    col = mix(col, patch_color.rgb, patch * 0.55);
    ALBEDO = col;
    ROUGHNESS = 0.92;
}

shader_type spatial;
render_mode diffuse_burley, specular_schlick_ggx;

uniform vec4 base_color : source_color = vec4(0.78, 0.70, 0.58, 1.0);
uniform vec4 dirt_color : source_color = vec4(0.33, 0.29, 0.24, 1.0);
uniform float dirt_strength : hint_range(0.0, 0.5) = 0.16;
uniform float roughness_base : hint_range(0.2, 1.0) = 0.82;
uniform float variation_scale = 0.35;

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 345.45));
    p += dot(p, p + 34.345);
    return fract(p.x * p.y);
}

float value_noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a,b,f.x), mix(c,d,f.x), f.y);
}

void fragment() {
    vec3 wp = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
    float n = value_noise(wp.xz * variation_scale);
    float low_dirt = clamp(1.0 - wp.y / 4.0, 0.0, 1.0);
    float grime = clamp((0.35 + 0.65 * n) * low_dirt * dirt_strength, 0.0, 0.45);
    ALBEDO = mix(base_color.rgb * (0.90 + 0.16 * n), dirt_color.rgb, grime);
    ROUGHNESS = clamp(roughness_base + (n - 0.5) * 0.18, 0.45, 1.0);
}
